import * as React from 'react';
import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import Container from '@mui/material/Container';
import Grid from '@mui/material/Grid2';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import WorkspacePremiumOutlinedIcon from '@mui/icons-material/WorkspacePremiumOutlined';
import SupportOutlinedIcon from '@mui/icons-material/SupportOutlined';
import SavingsOutlinedIcon from '@mui/icons-material/SavingsOutlined';

const items = [
  {
    icon: <WorkspacePremiumOutlinedIcon sx={{ fontSize: 40, color: 'primary.main' }} />,
    title: 'Experience',
    description:
      'Decades of collective wisdom. Leverage our extensive experience to avoid common pitfalls and accelerate your business growth.',
  },
  {
    icon: <SupportOutlinedIcon sx={{ fontSize: 40, color: 'primary.main' }} />,
    title: 'Quick Support',
    description:
      'We are your reliable partner, always there when you need us, ensuring smooth operations at every stage of your growth.',
  },
  {
    icon: <SavingsOutlinedIcon sx={{ fontSize: 40, color: 'primary.main' }} />,
    title: 'Cost Savings',
    description:
      'Maximising impact, minimising costs efficiency is key. We provide cost-effective solutions without compromising on quality.',
  },
];

export default function Highlights() {
  return (
    <Box
      id="highlights"
      sx={{
        pt: { xs: 4, sm: 12 },
        pb: { xs: 8, sm: 16 },
        color: 'white',
        bgcolor: '#030516',
      }}
    >
      <Container
        sx={{
          position: 'relative',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: { xs: 3, sm: 6 },
        }}
      >
        <Box
          sx={{
            width: { sm: '100%', md: '60%' },
            textAlign: { sm: 'left', md: 'center' },
          }}
        >
          <Typography 
            component="h2" 
            variant="h4" 
            gutterBottom
            sx={{
              textAlign: 'center',
              mb: 4
            }}
          >
            Your best call for B2B/B2C product innovation
          </Typography>
        </Box>
        <Grid container spacing={3}>
          {items.map((item, index) => (
            <Grid size={{ xs: 12, sm: 6, md: 4 }} key={index}>
              <Stack
                direction="column"
                component={Card}
                spacing={2}
                useFlexGap
                sx={{
                  color: 'inherit',
                  p: 3,
                  height: '100%',
                  borderColor: 'hsla(220, 25%, 25%, 0.3)',
                  backgroundColor: '#0C2645',
                  transition: 'transform 0.3s ease-in-out',
                  '&:hover': {
                    transform: 'translateY(-8px)',
                    backgroundColor: '#0C2645',
                  },
                }}
              >
                <Box 
                  sx={{ 
                    opacity: 1,
                    display: 'flex',
                    justifyContent: 'center',
                    alignItems: 'center',
                    width: '100%'
                  }}
                >
                  {item.icon}
                </Box>
                <div>
                  <Typography 
                    gutterBottom 
                    sx={{ 
                      fontWeight: 'medium',
                      color: 'primary.main',
                      textAlign: 'center'
                    }}
                  >
                    {item.title}
                  </Typography>
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      color: 'grey.300',
                      textAlign: 'center'
                    }}
                  >
                    {item.description}
                  </Typography>
                </div>
              </Stack>
            </Grid>
          ))}
        </Grid>
      </Container>
    </Box>
  );
}
